#undef HWY_TARGET_INCLUDE
#define HWY_TARGET_INCLUDE "highway-inl.h"

#include "hwy/foreach_target.h"

#include "hwy/highway.h"
#include "kernels.h"

#include HWY_TARGET_INCLUDE

#if HWY_ONCE

namespace stdlib {
	namespace blas {
		namespace ext {
			namespace base {
				namespace dsumpw {

					HWY_EXPORT( DsumpwHighway );

					static double DispatchDsumpwHighway( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
						return HWY_DYNAMIC_DISPATCH( DsumpwHighway )( N, X, strideX, offsetX );
					}

				} // namespace dsumpw
			} // namespace base
		} // namespace ext
	} // namespace blas
} // namespace stdlib

extern "C" double API_SUFFIX( stdlib_strided_dsumpw_ndarray_highway )( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	return stdlib::blas::ext::base::dsumpw::DispatchDsumpwHighway( N, X, strideX, offsetX );
}

#endif
